contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 id, uint256 mintId) public payable {
        require(to != address(0), "recipient must be non-zero");
        require(mintId == id, "mint the same key used in the transfer");

        // Previous token owner, observed before the transfer.
        address ownerBefore = c.ownerOf(id);

        // Drive the public entry: transferFrom(from, to, id).
        // msg.sender is this test contract. For success we need authorization,
        // so from must be this contract (the owner after minting).
        bool reverted;
        try c.transferFrom(from, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: on a successful transfer, ownerOf(id) must equal the recipient.
        if (!reverted) {
            assert(c.ownerOf(id) == to);
        } else {
            // If the transfer reverted, the original owner must be unchanged.
            assert(c.ownerOf(id) == ownerBefore);
        }
    }
}

