        c.transferFrom(address(0xdead), address(this), id);

        // Read the owner before the deciding call.
        address ownerBefore = c.ownerOf(id);

        // Deciding call: transferFrom this contract to `to`.
        bool success;
        try c.transferFrom(address(this), to, id) {
            success = true;
        } catch {
            success = false;
