contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address probe) public payable {
        require(probe != address(0), "probe must be nonzero");

        uint256 zeroTokenId = 0;
        uint256 maxTokenId = type(uint256).max;

        address zeroOwner;
        address maxOwner;
        bool zeroReverted;
        bool maxReverted;

        // Read-only external calls are allowed in assertions/requires, but we can
        // also drive them as top-level statements by storing the result.
        try c.ownerOf(zeroTokenId) returns (address o) { zeroOwner = o; zeroReverted = false; }
        catch { zeroReverted = true; }

        try c.ownerOf(maxTokenId) returns (address o) { maxOwner = o; maxReverted = false; }
        catch { maxReverted = true; }

        // If ownerOf(zeroTokenId) succeeds then the returned owner must be nonzero.
        // If it reverts, that token is not minted. Same for maxTokenId.
        // This is a general rule about the minting status of any token id we probe.
        assert(
            (zeroReverted || zeroOwner != address(0)) &&
            (maxReverted || maxOwner != address(0))
        );

        // Additionally, calling ownerOf on an address with no tokens must revert,
        // regardless of other state, because the ERC721 balanceOf override reports
        // balance as type(uint256).max for any nonzero owner. The probe address is
        // guaranteed nonzero by the precondition; ownerOf on probe reverts only if
        // the token has not been minted. Since the test contract cannot mint tokens,
        // this call must revert for any probe. Observe via try/catch.
        bool probeReverted;
        try c.ownerOf(uint256(uint160(probe))) returns (address) { probeReverted = false; }
        catch { probeReverted = true; }

        assert(probeReverted);
    }
}

