        // Deciding call: safeTransferFrom on an unminted token id must revert.
        bool reverted = false;
        try c.safeTransferFrom(address(this), address(0x1), tokenId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}

